template.script:
(function () {
    function initModal() {
        var el = document.getElementById('ve-success-modal');
        if (!el) { return; }

        // Inline styles as a safety net: the modal must always be
        // visible and closable even if the CSS bundle serving
        // .ve-modal-overlay/.ve-modal-open is stale or hasn't
        // regenerated yet - we never want body scroll locked
        // with nothing visible on screen to unlock it.
        function hide() {
            el.classList.remove('ve-modal-open');
            el.style.display = 'none';
            document.body.classList.remove('ve-modal-open-body');
            document.body.style.overflow = '';
        }
        function show() {
            el.classList.add('ve-modal-open');
            el.style.display = 'flex';
            el.style.position = 'fixed';
            el.style.inset = '0';
            el.style.zIndex = '10500';
            el.style.alignItems = 'center';
            el.style.justifyContent = 'center';
            el.style.background = 'rgba(13,27,42,0.7)';
            document.body.classList.add('ve-modal-open-body');
            document.body.style.overflow = 'hidden';
        }

        el.querySelectorAll('.ve-modal-close, .ve-modal-close-btn').forEach(function (btn) {
            btn.addEventListener('click', hide);
        });
        el.addEventListener('click', function (e) {
            if (e.target === el) { hide(); }
        });
        document.addEventListener('keydown', function (e) {
            if (e.key === 'Escape') { hide(); }
        });

        show();
    }
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initModal);
    } else {
        initModal();
    }
})();
